    RAS_TYPE_STANDARD       = 0x1,
    RAS_TYPE_BYTE_ENCODED       = 0x2,
    RAS_TYPE_RGB_FORMAT     = 0x3,
    RAS_TYPE_TIFF_FORMAT        = 0x4,
    RAS_TYPE_IFF_FORMAT     = 0x5,
    RAS_TYPE_EXPERIMENTAL       = 0xFFFF
};

